<template><div class="food-page"><div class="page-intro"><div><div class="eyebrow">QINGHE CAMPUS / {{isStore?'MERCHANTS':'MENU'}}</div><h1>{{isStore?(platform?'商家管理':'我的店铺'):'菜品管理'}}</h1><p>{{isStore?'管理店铺信息、营业状态和商家账号。':'用心做好每一道菜。从这里管理菜单、价格和可售库存。'}}</p></div><el-button v-if="!isStore||platform" type="primary" size="large" @click="edit()">＋ {{isStore?'新增商家':'新增菜品'}}</el-button></div>
<el-card shadow="never"><div class="toolbar"><el-input v-model="search" :placeholder="isStore?'搜索商家名称':'搜索菜品或商家名称'" clearable style="width:260px"/><el-select v-if="!isStore" v-model="storeFilter" clearable filterable remote :remote-method="loadStores" :loading="storesLoading" placeholder="全部商家" style="width:200px"><el-option v-for="s in stores" :key="s.id" :label="s.name" :value="s.id"/></el-select><div class="spacer"/><el-button v-if="!isStore||platform" @click="importVisible=true">批量导入 CSV</el-button><el-button @click="load">刷新</el-button></div>
<el-table v-loading="loading" :data="filtered" row-key="id"><el-table-column label="编号" prop="id" width="70"/><el-table-column :label="isStore?'商家':'菜品'" min-width="240"><template #default="{row}"><div class="name-cell"><img :src="asset(row.image)"/><div><strong>{{row.name}}</strong><div class="subtext">{{isStore?row.zone:row.store_name}} · {{row.category}}</div></div></div></template></el-table-column><el-table-column v-if="isStore" label="商家账号" prop="accounts" min-width="140"><template #default="{row}">{{row.accounts||'暂未开通'}}</template></el-table-column><el-table-column v-if="!isStore" label="价格" width="100"><template #default="{row}">¥{{money(row.price)}}</template></el-table-column><el-table-column v-if="!isStore" label="库存" prop="stock" width="90"/><el-table-column label="销量" prop="sales" width="100"/><el-table-column v-if="isStore" label="营业时间 / 配送范围" min-width="180"><template #default="{row}">{{row.opening_text}}<div class="subtext">{{row.delivery_radius?row.delivery_radius+' 米内':'不限配送距离'}}</div></template></el-table-column><el-table-column label="状态" width="130"><template #default="{row}"><el-tag :type="row.active===1?'success':'info'">{{row.active===1?(isStore?(row.open_now?'营业中':'未到营业时间'):'已上架'):(isStore?'休息中':'已下架')}}</el-tag></template></el-table-column><el-table-column label="操作" width="210" fixed="right"><template #default="{row}"><el-button v-if="!isStore" link type="primary" @click="optionEditor.open(row)">规格加料</el-button><el-button link type="primary" @click="edit(row)">编辑</el-button><el-button link :type="row.active?'warning':'success'" @click="toggle(row)">{{row.active?(isStore?'休息':'下架'):(isStore?'营业':'上架')}}</el-button><el-button v-if="isStore&&platform" link type="primary" @click="account(row)">开通账号</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="total, prev, pager, next" @current-change="load" style="margin-top:20px"/><div class="table-note">共 {{total}} 条记录{{isStore?'':' · 库存为当前可售数量，未支付订单会预占库存'}}</div></el-card>
<el-dialog v-model="visible" :title="(form.id?'编辑':'新增')+(isStore?'商家':'菜品')" width="660px" append-to-body><el-form label-width="100px"><el-form-item v-if="!isStore" label="所属商家" required><el-select v-model="form.store_id" filterable remote :remote-method="loadStores" :loading="storesLoading" :disabled="!!form.id" style="width:100%"><el-option v-for="s in stores" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item><el-form-item label="名称" required><el-input v-model="form.name" :maxlength="isStore?80:100"/></el-form-item><el-form-item label="分类" required><el-input v-model="form.category" placeholder="例如：家常菜 / 招牌必点"/></el-form-item><el-form-item v-if="isStore" label="所在区域" required><el-select v-model="form.zone" allow-create filterable><el-option v-for="z in ['一食堂','二食堂','商业街']" :key="z" :label="z" :value="z"/></el-select></el-form-item><el-form-item label="简介"><el-input v-model="form.description" type="textarea" maxlength="500"/></el-form-item><el-form-item label="图片" required><div style="width:100%"><el-input v-model="form.image" placeholder="图片地址，或使用下方上传"/><el-upload :action="uploadUrl" :headers="uploadHeaders" :show-file-list="false" :on-success="uploaded" :before-upload="beforeUpload" style="margin-top:10px"><el-button>上传 JPG / PNG 图片</el-button></el-upload></div></el-form-item><template v-if="isStore"><el-form-item label="配送时间"><el-input-number v-model="form.minutes" :min="1" :max="180"/> 分钟</el-form-item><el-form-item label="GPS 纬度"><el-input-number v-model="form.latitude" :min="-90" :max="90" :precision="6" :value-on-clear="null"/></el-form-item><el-form-item label="GPS 经度"><el-input-number v-model="form.longitude" :min="-180" :max="180" :precision="6" :value-on-clear="null"/><div class="subtext">两项一起填写或留空，使用 WGS84 坐标。未填写时显示“距离待完善”，距离由顾客定位实时计算。</div></el-form-item><el-form-item label="开始营业"><el-time-picker v-model="form.open_time" value-format="HH:mm" format="HH:mm" placeholder="留空表示全天"/></el-form-item><el-form-item label="结束营业"><el-time-picker v-model="form.close_time" value-format="HH:mm" format="HH:mm" placeholder="支持跨午夜"/><div class="subtext">北京时间，两项均留空为全天营业；结束早于开始表示次日结束。</div></el-form-item><el-form-item label="分段营业"><el-input v-model="form.business_periods" placeholder="07:00-10:00,11:00-14:00,17:00-21:00"/><div class="subtext">选填，最多4段，填写后优先于上方单时段；支持跨午夜。</div></el-form-item><el-form-item label="开放预约"><el-switch v-model="form.reservation_enabled" :active-value="1" :inactive-value="0"/></el-form-item><el-form-item v-if="form.reservation_enabled" label="预约天数"><el-input-number v-model="form.reservation_days" :min="1" :max="7"/> 天（含今天）</el-form-item><el-form-item v-if="form.reservation_enabled" label="提前备餐"><el-input-number v-model="form.lead_minutes" :min="15" :max="240"/> 分钟</el-form-item><el-form-item label="配送半径"><el-input-number v-model="form.delivery_radius" :min="0" :max="50000"/> 米<div class="subtext">0 表示不限范围；设置范围前请填写店铺坐标。按收货点直线距离校验，自取不受限。</div></el-form-item><el-form-item label="起送金额"><el-input-number v-model="minimumYuan" :min="0" :precision="2"/> 元</el-form-item><el-form-item label="配送费"><el-input-number v-model="deliveryYuan" :min="0" :precision="2"/> 元</el-form-item><el-form-item label="商家电话"><el-input v-model="form.phone" maxlength="30"/></el-form-item><el-form-item label="公告"><el-input v-model="form.notice" type="textarea" maxlength="500"/></el-form-item></template><template v-else><el-form-item label="价格" required><el-input-number v-model="priceYuan" :min="0.01" :precision="2" :max="10000"/> 元</el-form-item><el-form-item label="可售库存" required><el-input-number v-model="form.stock" :min="0" :max="1000000"/></el-form-item></template><el-form-item label="状态"><el-switch v-model="form.active" :active-value="1" :inactive-value="0"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog>
<el-dialog v-model="accountVisible" title="开通商家后台账号" width="480px"><el-alert :title="'绑定商家：'+accountStore.name+'。该账号只能访问本店数据。'" :closable="false" type="info"/><el-form label-width="80px" style="margin-top:24px"><el-form-item label="登录账号"><el-input v-model="accountForm.username" placeholder="4至30位字母、数字、下划线"/></el-form-item><el-form-item label="初始密码"><el-input v-model="accountForm.password" type="password" show-password placeholder="10至50位密码"/></el-form-item></el-form><template #footer><el-button @click="accountVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="createAccount">开通账号</el-button></template></el-dialog>
<el-dialog v-model="importVisible" :title="'批量导入'+(isStore?'商家':'菜品')" width="760px"><el-alert title="先下载模板，用 Excel 编辑并另存为 UTF-8 CSV。每批最多500行，仅新增；任一行不合法整批回滚。金额单位为分。" :closable="false" type="info"/><div class="toolbar" style="margin-top:20px"><el-button @click="downloadTemplate">下载 CSV 模板</el-button><input type="file" accept=".csv" @change="parseFile"/></div><el-alert v-if="importError" :title="importError" type="error" :closable="false"/><el-table :data="importRows.slice(0,8)" max-height="300"><el-table-column v-for="field in importFields.slice(0,6)" :key="field" :prop="field" :label="field" min-width="110"/></el-table><p class="subtext">已读取 {{importRows.length}} 行，预览前8行。商家ID可在商家管理列表查看。</p><template #footer><el-button @click="importVisible=false">取消</el-button><el-button type="primary" :loading="saving" :disabled="!importRows.length||!!importError" @click="doImport">确认导入 {{importRows.length}} 行</el-button></template></el-dialog>
<ProductOptions ref="optionEditor"/></div></template>
<script setup>
import {ref,computed,watch,onMounted,onBeforeUnmount} from 'vue';import ProductOptions from './ProductOptions.vue';const optionEditor=ref();import {ElMessage,ElMessageBox} from 'element-plus';import {foodGet,foodPost,money} from '@/api/food';import {getToken} from '@/utils/auth';import {parseCsv,serializeCsv} from './csv';
const props=defineProps({kind:{type:String,required:true}}),isStore=computed(()=>props.kind==='stores');const rows=ref([]),stores=ref([]),platform=ref(false),loading=ref(false),saving=ref(false),search=ref(''),storeFilter=ref(),visible=ref(false),form=ref({}),accountVisible=ref(false),accountStore=ref({}),accountForm=ref({}),importVisible=ref(false),importRows=ref([]),importError=ref('');
const uploadUrl=import.meta.env.VITE_APP_BASE_API+'/common/upload',uploadHeaders={Authorization:'Bearer '+getToken()};const asset=url=>url?.startsWith('/profile/')?import.meta.env.VITE_APP_BASE_API+url:url;
const filtered=computed(()=>rows.value);const priceYuan=computed({get:()=>form.value.price/100,set:v=>form.value.price=Math.round(v*100)}),minimumYuan=computed({get:()=>form.value.minimum/100,set:v=>form.value.minimum=Math.round(v*100)}),deliveryYuan=computed({get:()=>form.value.delivery_fee/100,set:v=>form.value.delivery_fee=Math.round(v*100)});
const importFields=computed(()=>isStore.value?['name','category','zone','description','image','minutes','latitude','longitude','delivery_fee','minimum','notice','phone','active','open_time','close_time','delivery_radius']:['store_id','name','category','description','image','price','stock','active']);
const page=ref(1),total=ref(0),storesLoading=ref(false);let revision=0,storeRevision=0,searchTimer;
async function load(){const ticket=++revision;loading.value=true;try{const r=await foodGet('/catalog/'+props.kind,{page:page.value,q:search.value.trim(),storeId:storeFilter.value});if(ticket===revision){rows.value=r.data.rows;total.value=r.data.total}}finally{if(ticket===revision)loading.value=false}}
async function loadStores(q=''){const ticket=++storeRevision;storesLoading.value=true;try{const r=await foodGet('/catalog/stores',{q,pageSize:20});if(ticket===storeRevision)stores.value=r.data.rows}finally{if(ticket===storeRevision)storesLoading.value=false}}
watch(search,()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{page.value=1;load()},300)});watch(storeFilter,()=>{page.value=1;load()});onBeforeUnmount(()=>{clearTimeout(searchTimer);revision++;storeRevision++});
function edit(row){if(row?.store_id&&!stores.value.some(s=>s.id===row.store_id))stores.value.push({id:row.store_id,name:row.store_name});form.value=row?{...row}:{name:'',category:isStore.value?'家常菜':'招牌必点',zone:'一食堂',description:'',image:'/static/food/rice.jpg',minutes:30,distance:0,latitude:null,longitude:null,business_periods:'',reservation_enabled:0,reservation_days:3,lead_minutes:30,open_time:'',close_time:'',delivery_radius:0,delivery_fee:200,minimum:1300,notice:'欢迎光临',phone:'',active:1,store_id:stores.value[0]?.id,price:1500,stock:100};visible.value=true}
async function save(){saving.value=true;try{await foodPost('/'+props.kind,form.value);ElMessage.success('保存成功');visible.value=false;await load()}finally{saving.value=false}}
async function toggle(row){await ElMessageBox.confirm('确认调整「'+row.name+'」的状态？','调整状态');await foodPost('/'+props.kind,{...row,active:row.active?0:1});ElMessage.success('状态已更新');load()}
function account(row){accountStore.value=row;accountForm.value={};accountVisible.value=true}async function createAccount(){saving.value=true;try{await foodPost('/stores/'+accountStore.value.id+'/account',accountForm.value);ElMessage.success('账号开通成功，可使用同一登录地址进入专属商家后台');accountVisible.value=false;await load()}finally{saving.value=false}}
function uploaded(r){if(r.code===200){form.value.image=r.fileName;ElMessage.success('上传成功')}else ElMessage.error(r.msg||'上传失败')}function beforeUpload(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024){ElMessage.error('请选择5MB内的JPG、PNG或WebP图片');return false}return true}
function downloadTemplate(){const row=isStore.value?['示例餐厅','家常菜','一食堂','每天现做','/static/food/rice.jpg',30,'','',200,1300,'欢迎光临','13800000000',1,'','',0]:[stores.value[0]?.id||1,'招牌鸡腿饭','招牌必点','鸡腿配时蔬','/static/food/rice.jpg',1500,100,1];const blob=new Blob(['\ufeff'+serializeCsv([importFields.value,row])],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(isStore.value?'商家':'菜品')+'导入模板.csv';a.click();URL.revokeObjectURL(url)}
async function parseFile(e){importError.value='';importRows.value=[];const file=e.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw Error('文件不能超过2MB');const data=parseCsv(await file.text());const headers=data.shift().map(h=>h.trim().replace(/^\ufeff/,''));for(const field of importFields.value.filter(f=>!['latitude','longitude','open_time','close_time','delivery_radius'].includes(f)))if(!headers.includes(field))throw Error('缺少列：'+field);const numbers=['store_id','minutes','distance','delivery_fee','minimum','price','stock','active','delivery_radius'];importRows.value=data.filter(row=>row.some(v=>v.trim())).map((row,i)=>{if(row.length!==headers.length)throw Error('第'+(i+2)+'行列数不正确');return Object.fromEntries(headers.map((h,j)=>{if(['latitude','longitude'].includes(h)){const value=row[j].trim();if(value!==''&&!Number.isFinite(Number(value)))throw Error('第'+(i+2)+'行经纬度必须为数字');return [h,value===''?null:Number(value)]}return [h,numbers.includes(h)?Number(row[j]):row[j]]}))});if(importRows.value.length>500)throw Error('每批不能超过500行')}catch(e){importError.value=e.message}}
async function doImport(){saving.value=true;try{await foodPost('/'+props.kind+'/import',importRows.value);ElMessage.success('成功导入 '+importRows.value.length+' 行');importVisible.value=false;importRows.value=[];await load()}finally{saving.value=false}}onMounted(async()=>{platform.value=(await foodGet('/scope')).data.platform;await Promise.all([load(),loadStores()])});
</script>
<style scoped>.food-page{padding:30px;background:#f6f8f5;min-height:calc(100vh - 85px)}.page-intro{display:flex;align-items:center;justify-content:space-between;margin-bottom:24px}.eyebrow{font-size:11px;color:#8a9a86;letter-spacing:2px}h1{font-size:27px;color:#294936;margin:12px 0}p{color:#899488;font-size:13px}.toolbar{display:flex;gap:12px;align-items:center;margin-bottom:22px;flex-wrap:wrap}.spacer{flex:1}.name-cell{display:flex;align-items:center;gap:14px;padding:8px 0}.name-cell img{width:56px;height:56px;object-fit:cover;border-radius:12px}.subtext{color:#95a08f;font-size:12px;margin-top:7px}.table-note{font-size:12px;color:#98a391;padding:20px 0 0}.el-card{border-radius:14px;border-color:#e8eee4}.el-button--primary{--el-color-primary:#487652;--el-color-primary-light-3:#729979;--el-color-primary-dark-2:#315f3d}</style>
